function solve({config,state,event}){
  if(state===null)state={v:config.initial,d:String(config.initial),e:null,x:false};
  var s={v:state.v,d:state.d,e:state.e,x:state.x},t=event.type;
  if(t==='mode')s.x=event.disabled;
  else if(t==='cancel'){s.d=String(s.v);s.e=null}
  else if(!s.x&&t==='input'){s.d=event.text;s.e=null}
  else if(!s.x&&t==='commit'){
    var z=s.d,m=/^[+-]?[0-9]+$/.test(z),n=m?Number(z):NaN;
    if(!m||!Number.isSafeInteger(n))s.e='invalid';
    else{
      var q=(n-config.min)/config.step,k=Math.floor(q),r=k*config.step+config.min;
      if(k<=0)r=config.min;
      else if(r>=config.max)r=config.max;
      else{var u=r+config.step;if(n-r>u-n)r=u}
      s.v=r;s.d=String(r);s.e=null;
    }
  }else if(!s.x&&t==='step'){
    var k=Math.round((s.v-config.min)/config.step)+(event.direction<0?-1:1),r=config.min+k*config.step;
    if(r<config.min)r=config.min;if(r>config.max)r=config.max;
    s.v=r;s.d=String(r);s.e=null;
  }
  return {state:s,output:{value:s.v,draft:s.d,dirty:s.d!==String(s.v),error:s.e,disabled:s.x}};
}
